        + approach_sample_offset))->lateral_scale = 1.0f;
    ((PathAttachmentSample*)((char*)primary_samples
        + approach_sample_offset))->transform.Identity();
    float z = (float)i;
    ((PathAttachmentSample*)((char*)primary_samples
        + approach_sample_offset))->transform.position.x =
